-- PeerSlate Break Feed: 200 Daily Quote Seed Items
-- How to use:
-- 1. Open Azure SQL Database > Query editor.
-- 2. Paste this full file into a new query.
-- 3. Click Run.
-- 4. Then run: SELECT COUNT(*) FROM content_items WHERE content_type = 'quote' AND mood = 'Break';


SELECT COUNT(*) AS break_quote_count FROM content_items WHERE content_type = 'quote' AND mood = 'Break';
